#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> farthest(int start, const vector<vector<int>>& graph, bool saveParent) {
    int n = graph.size();
    vector<int> dist(n, -1);
    vector<int> parent(n, -1);
    queue<int> q;

    dist[start] = 0;
    q.push(start);
    int farthestNode = start;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (dist[u] > dist[farthestNode]) {
            farthestNode = u;
        }

        for (int v : graph[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    return {farthestNode, saveParent ? parent : vector<int>()};
}

long long countAtDistance(int start, int blocked, int target,
                          const vector<vector<int>>& graph) {
    long long count = 0;
    vector<tuple<int, int, int>> stack;
    stack.emplace_back(start, blocked, 0);

    while (!stack.empty()) {
        auto [u, parent, depth] = stack.back();
        stack.pop_back();

        if (depth == target) {
            ++count;
            continue;
        }

        for (int v : graph[u]) {
            if (v != parent) {
                stack.emplace_back(v, u, depth + 1);
            }
        }
    }

    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> graph(n);
    for (int i = 0; i < n - 1; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        graph[x].push_back(y);
        graph[y].push_back(x);
    }

    int a = farthest(0, graph, false).first;
    auto [b, parent] = farthest(a, graph, true);

    vector<int> path;
    for (int v = b; v != -1; v = parent[v]) {
        path.push_back(v);
        if (v == a) break;
    }

    int diameter = static_cast<int>(path.size()) - 1;
    long long ways = 0;

    if (diameter % 2 == 0) {
        int center = path[diameter / 2];
        int radius = diameter / 2;
        long long accumulated = 0;

        for (int neighbor : graph[center]) {
            long long count = countAtDistance(neighbor, center, radius - 1, graph);
            ways += accumulated * count;
            accumulated += count;
        }
    } else {
        int radius = diameter / 2;
        int center1 = path[diameter / 2];
        int center2 = path[diameter / 2 + 1];

        long long leftCount = countAtDistance(center1, center2, radius, graph);
        long long rightCount = countAtDistance(center2, center1, radius, graph);
        ways = leftCount * rightCount;
    }

    cout << diameter + 1 << '\n' << ways << '\n';
    return 0;
}
